"use client";

import * as React from "react";
import { ArrowUp, Check, Clock, Mic, Minus, UserRound } from "lucide-react";

type DivProps = React.ComponentProps<"div">;

export type AvatarStatus = "online" | "away" | "busy" | "offline" | "speaking" | "uploading";

/** CSS colours that replace the default ring colour per status, e.g. `{ online: "var(--color-chart-3)" }`. */
export type AvatarStatusTone = { [status in AvatarStatus]?: string };

export type AvatarStatusRingProps = DivProps & {
  /** Avatar image. Without it, or when it fails to load, the fallback is shown. */
  src?: string;
  /** Accessible name when `name` is absent. */
  alt: string;
  name?: string;
  /** Avatar diameter in px. Default 40. The ring adds 4 px plus its width on every side. */
  size?: number;
  /** Shown when the image is missing or fails. Default: a neutral silhouette. */
  fallback?: React.ReactNode;
  status: AvatarStatus;
  /** 0..1 voice level while `status="speaking"`; the ring thickens with it. Default 0.6. */
  level?: number;
  /** 0..1 while `status="uploading"`; the ring fills clockwise from 12 o'clock. */
  progress?: number;
  /** Small status glyph (mic, clock, arrow, minus) at the lower right. Default true. */
  showIcon?: boolean;
  /** Ring stroke in px. Default 2.5. */
  ringWidth?: number;
  tone?: AvatarStatusTone;
  /** Replaces the status phrase in the tooltip and the accessible label. */
  statusLabel?: string;
  /** Hover / focus tooltip with name and status. Default true. */
  tooltip?: boolean;
  /** Announce status changes in a polite live region. Default false. */
  announce?: boolean;
  /** Colour behind the glyph and the backdrop disc; match the surface the avatar sits on. Default `var(--color-background)`. */
  surface?: string;
  /** Fill the ring gap with `surface` so stacked avatars read cleanly. Default false. */
  backdrop?: boolean;
  /** Delay before the ring draws itself in on mount, in ms. */
  drawDelay?: number;
};

export type AvatarStatusRingGroupItem = {
  id?: string;
  src?: string;
  alt: string;
  name?: string;
  status: AvatarStatus;
  level?: number;
  progress?: number;
  tone?: AvatarStatusTone;
  statusLabel?: string;
  fallback?: React.ReactNode;
};

export type AvatarStatusRingGroupProps = DivProps & {
  items: AvatarStatusRingGroupItem[];
  /** How many avatars to show before the "+n" chip. Default 5. */
  max?: number;
  /** Avatar diameter in px. Default 32. */
  size?: number;
  /** How far each avatar overlaps the previous one, in px. Default 35 % of `size`. */
  overlap?: number;
  /** Ring stroke in px. Default 2. */
  ringWidth?: number;
  /** Status glyphs on each avatar. Default: only when `size` is 40 or more. */
  showIcon?: boolean;
  /** Colour of the discs behind the rings. Default `var(--color-background)`. */
  surface?: string;
  /** Announce status changes of any member in one polite live region. Default false. */
  announce?: boolean;
  overflowLabel?: (hidden: number) => string;
  /** Delay before the first ring draws in, ms. Default 0. */
  drawDelay?: number;
  /** Extra delay per avatar, ms. Default 80. */
  stagger?: number;
  "aria-label"?: string;
};

const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const EASE_DRAW = "cubic-bezier(0.4, 0, 0.2, 1)";
/** Avatar edge to the centre line of the ring, px. */
const GAP = 4;
const DRAW_MS = 360;
const PATTERN_MS = 360;
const COLOR_MS = 240;
const GLYPH_MS = 220;
const CHECK_MS = 1100;
/** Share of the remaining distance the stroke width covers per frame while following `level`. */
const DAMPING = 0.2;
/** How far the halo moves out from the ring at full level, px. */
const HALO_GROW = 3;
const HALO_OPACITY = 0.25;
/** One dash covering the whole path (pathLength = 1): the arc the dash offset carves out of it. */
const FULL = "1px 1px";
const REDUCED_QUERY = "(prefers-reduced-motion: reduce)";

const STATUS_COLOR = {
  online: "var(--color-chart-2)",
  away: "var(--asr-away)",
  busy: "var(--color-destructive)",
  offline: "var(--color-border)",
  speaking: "var(--color-chart-2)",
  uploading: "var(--color-chart-1)",
} as const;

export const AVATAR_STATUS_LABEL = {
  online: "Online",
  away: "Away",
  busy: "Busy",
  offline: "Offline",
  speaking: "Speaking",
  uploading: "Uploading",
} as const;

type Glyph = "mic" | "clock" | "upload" | "minus" | "check";

const STATUS_GLYPH: { [status in AvatarStatus]: Glyph | null } = {
  online: null,
  away: "clock",
  busy: "minus",
  offline: null,
  speaking: "mic",
  uploading: "upload",
};

const GLYPH_ICON: { [glyph in Glyph]: React.ReactNode } = {
  mic: <Mic strokeWidth={2.5} aria-hidden="true" />,
  clock: <Clock strokeWidth={2.5} aria-hidden="true" />,
  upload: <ArrowUp strokeWidth={2.75} aria-hidden="true" />,
  minus: <Minus strokeWidth={3} aria-hidden="true" />,
  check: <Check strokeWidth={3} aria-hidden="true" />,
};

const subscribeReduced = (onChange: () => void) => {
  const media = window.matchMedia(REDUCED_QUERY);
  media.addEventListener("change", onChange);
  return () => media.removeEventListener("change", onChange);
};
const readReduced = () => window.matchMedia(REDUCED_QUERY).matches;
const readReducedOnServer = () => true;

function useReducedMotion() {
  return React.useSyncExternalStore(subscribeReduced, readReduced, readReducedOnServer);
}

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

function canAnimate(node: Element | null): node is HTMLElement {
  return !!node && typeof (node as HTMLElement).animate === "function";
}

type Geometry = { box: number; c: number; r: number; solid: string; dashed: string };

/** Ring geometry in px. Dash lengths are in pathLength units (the whole circle is 1) so a dash period stays about 10 px at any size. */
function geometry(size: number, ringWidth: number): Geometry {
  const box = size + 2 * (GAP + ringWidth);
  const r = size / 2 + GAP;
  const period = 1 / Math.max(8, Math.round((2 * Math.PI * r) / 10));
  return { box, c: box / 2, r, solid: `${period}px 0px`, dashed: `${period * 0.35}px ${period * 0.65}px` };
}

type DashMode = "solid" | "dashed" | "arc";

function modeOf(dasharray: string): DashMode {
  const [dash = 1, gap = 0] = dasharray.split(",").map((part) => Number.parseFloat(part));
  if (!Number.isFinite(dash) || !Number.isFinite(gap) || gap < 1e-6) return "solid";
  if (Math.abs(dash - 1) < 1e-3 && Math.abs(gap - 1) < 1e-3) return "arc";
  return "dashed";
}

const offsetDuration = (delta: number) => Math.min(420, Math.max(160, delta * 1400));

const settle = (animation: Animation) => animation.finished.then(() => true, () => false);

type Latest = { status: AvatarStatus; progress: number; reduced: boolean; drawDelay: number };

export function AvatarStatusRing({
  src,
  alt,
  name,
  size = 40,
  fallback,
  status,
  level,
  progress,
  showIcon = true,
  ringWidth = 2.5,
  tone,
  statusLabel,
  tooltip = true,
  announce = false,
  surface = "var(--color-background)",
  backdrop = false,
  drawDelay = 0,
  tabIndex = 0,
  className = "",
  style,
  ref,
  onPointerEnter,
  onPointerLeave,
  onFocus,
  onBlur,
  ...rest
}: AvatarStatusRingProps) {
  const reduced = useReducedMotion();
  const geo = React.useMemo(() => geometry(size, ringWidth), [size, ringWidth]);
  const progressValue = clamp01(progress ?? 0);
  const uploading = status === "uploading";
  const displayName = name ?? alt;
  const percent = Math.round(progressValue * 100);
  const phrase = statusLabel ?? (uploading ? `${AVATAR_STATUS_LABEL.uploading} ${percent}%` : AVATAR_STATUS_LABEL[status]);
  const color = tone?.[status] ?? STATUS_COLOR[status];

  const rootRef = React.useRef(null as HTMLDivElement | null);
  const ringRef = React.useRef(null as SVGCircleElement | null);
  const haloRef = React.useRef(null as SVGCircleElement | null);
  const glyphRef = React.useRef(null as HTMLSpanElement | null);
  const imageRef = React.useRef(null as HTMLImageElement | null);
  const [failedSrc, setFailedSrc] = React.useState(null as string | null);
  const failed = failedSrc !== null && failedSrc === src;
  const [hovered, setHovered] = React.useState(false);
  const [focused, setFocused] = React.useState(false);

  React.useLayoutEffect(() => {
    const image = imageRef.current;
    if (src && image && image.complete && image.naturalWidth === 0) setFailedSrc(src);
  }, [src]);

  const latest = React.useRef({ status, progress: progressValue, reduced, drawDelay } as Latest);
  latest.current = { status, progress: progressValue, reduced, drawDelay };
  const seq = React.useRef(0);
  const running = React.useRef(null as Animation | null);
  const drawn = React.useRef(false);
  const initial = React.useRef({
    dash: reduced ? (status === "away" ? geo.dashed : uploading ? FULL : geo.solid) : FULL,
    offset: reduced ? (uploading ? 1 - progressValue : 0) : 1,
  });

  const tween = React.useCallback((ring: SVGCircleElement, frames: Keyframe[], options: KeyframeAnimationOptions) => {
    running.current?.cancel();
    const animation = ring.animate(frames, options);
    running.current = animation;
    return settle(animation);
  }, []);

  /** Moves the ring from whatever it shows now to what the props ask for, one visible step at a time. A newer call takes over mid-way. */
  const reconcile = React.useCallback(async (mount: boolean) => {
    const ring = ringRef.current;
    if (!ring) return;
    const token = ++seq.current;
    const alive = () => token === seq.current;
    const want = latest.current;
    const wantMode: DashMode = want.status === "uploading" ? "arc" : want.status === "away" ? "dashed" : "solid";
    const wantOffset = wantMode === "arc" ? 1 - want.progress : 0;
    const wantDash = wantMode === "arc" ? FULL : wantMode === "dashed" ? geo.dashed : geo.solid;
    const setDash = (value: string) => { ring.style.strokeDasharray = value; };
    const setOffset = (value: number) => { ring.style.strokeDashoffset = `${value}px`; };

    if (want.reduced || typeof ring.animate !== "function") {
      running.current?.cancel();
      running.current = null;
      setDash(wantDash);
      setOffset(wantOffset);
      return;
    }

    if (mount) {
      // Draw the ring in from 12 o'clock, then let the pattern settle.
      setDash(FULL);
      setOffset(wantOffset);
      const ok = await tween(ring, [{ strokeDashoffset: "1px" }, { strokeDashoffset: `${wantOffset}px` }], { duration: DRAW_MS, delay: want.drawDelay, easing: EASE_DRAW, fill: "backwards" });
      if (!ok || !alive() || wantMode === "arc") return;
      setDash(geo.solid);
      if (wantMode === "dashed") {
        setDash(geo.dashed);
        await tween(ring, [{ strokeDasharray: geo.solid }, { strokeDasharray: geo.dashed }], { duration: PATTERN_MS, easing: EASE });
      }
      return;
    }

    const computed = getComputedStyle(ring);
    const dashNow = computed.strokeDasharray;
    let offset = Number.parseFloat(computed.strokeDashoffset);
    if (!Number.isFinite(offset)) offset = wantOffset;
    let mode = modeOf(dashNow);

    // 1. A dashed ring closes up before anything else happens.
    if (mode === "dashed") {
      if (wantMode === "dashed") {
        setDash(geo.dashed);
        await tween(ring, [{ strokeDasharray: dashNow }, { strokeDasharray: geo.dashed }], { duration: PATTERN_MS, easing: EASE });
        return;
      }
      setDash(geo.solid);
      const ok = await tween(ring, [{ strokeDasharray: dashNow }, { strokeDasharray: geo.solid }], { duration: PATTERN_MS, easing: EASE });
      if (!ok || !alive()) return;
      mode = "solid";
      offset = 0;
    }

    // 2. Any solid ring can become a progress arc without a visible change; the arc then unwinds or fills to the new value.
    if (wantMode === "arc") {
      setDash(FULL);
      const delta = Math.abs(offset - wantOffset);
      setOffset(wantOffset);
      if (delta < 1e-4) return;
      await tween(ring, [{ strokeDashoffset: `${offset}px` }, { strokeDashoffset: `${wantOffset}px` }], { duration: offsetDuration(delta), easing: delta < 0.1 ? "linear" : EASE });
      return;
    }

    // 3. Leaving an arc: fill the ring first, then switch to the pattern.
    if (mode === "arc" && offset > 1e-4) {
      setOffset(0);
      const ok = await tween(ring, [{ strokeDashoffset: `${offset}px` }, { strokeDashoffset: "0px" }], { duration: offsetDuration(offset), easing: EASE });
      if (!ok || !alive()) return;
    }
    setOffset(0);
    setDash(geo.solid);
    if (wantMode === "dashed") {
      setDash(geo.dashed);
      await tween(ring, [{ strokeDasharray: geo.solid }, { strokeDasharray: geo.dashed }], { duration: PATTERN_MS, easing: EASE });
    }
  }, [geo, tween]);

  React.useLayoutEffect(() => {
    const mount = !drawn.current;
    drawn.current = true;
    void reconcile(mount);
  }, [status, progressValue, reduced, reconcile]);

  React.useEffect(() => () => {
    seq.current += 1;
    running.current?.cancel();
    running.current = null;
    drawn.current = false;
  }, []);

  const frame = React.useRef(0);
  const smooth = React.useRef(0);
  const levelTarget = React.useRef(0);

  const applyLevel = React.useCallback((value: number, halo: boolean) => {
    const ring = ringRef.current;
    const ripple = haloRef.current;
    if (ring) ring.style.strokeWidth = `${ringWidth * (1 + value)}px`;
    if (ripple) {
      ripple.setAttribute("r", String(geo.r + (ringWidth * (1 + value)) / 2 + 1 + HALO_GROW * value));
      ripple.style.opacity = String(halo ? HALO_OPACITY * Math.min(1, value * 2.2) : 0);
    }
  }, [ringWidth, geo.r]);

  React.useEffect(() => {
    const speaking = status === "speaking";
    const target = speaking ? clamp01(level ?? 0.6) : 0;
    levelTarget.current = target;
    if (reduced) {
      if (frame.current) cancelAnimationFrame(frame.current);
      frame.current = 0;
      smooth.current = target;
      applyLevel(speaking ? 0.6 : 0, false);
      return;
    }
    if (frame.current) return;
    const step = () => {
      const goal = levelTarget.current;
      const next = smooth.current + (goal - smooth.current) * DAMPING;
      smooth.current = Math.abs(next - goal) < 0.002 ? goal : next;
      applyLevel(smooth.current, true);
      frame.current = smooth.current === goal ? 0 : requestAnimationFrame(step);
    };
    frame.current = requestAnimationFrame(step);
  }, [status, level, reduced, applyLevel]);

  React.useEffect(() => () => {
    if (frame.current) cancelAnimationFrame(frame.current);
    frame.current = 0;
  }, []);

  const [celebrating, setCelebrating] = React.useState(false);
  const previous = React.useRef({ status, progress: progressValue });
  const celebrateTimer = React.useRef(0);

  React.useEffect(() => {
    const was = previous.current;
    previous.current = { status, progress: progressValue };
    if (was.status === "uploading" && status !== "uploading" && was.progress >= 0.98) {
      setCelebrating(true);
      window.clearTimeout(celebrateTimer.current);
      celebrateTimer.current = window.setTimeout(() => setCelebrating(false), CHECK_MS);
    }
  }, [status, progressValue]);

  React.useEffect(() => () => window.clearTimeout(celebrateTimer.current), []);

  const targetGlyph: Glyph | null = showIcon ? (celebrating ? "check" : STATUS_GLYPH[status]) : null;
  const [glyph, setGlyph] = React.useState(targetGlyph);
  const glyphAnimation = React.useRef(null as Animation | null);
  const glyphMounted = React.useRef(false);

  React.useLayoutEffect(() => {
    if (targetGlyph === glyph) return;
    if (targetGlyph !== null) { setGlyph(targetGlyph); return; }
    const node = glyphRef.current;
    if (reduced || !canAnimate(node)) { setGlyph(null); return; }
    glyphAnimation.current?.cancel();
    const animation = node.animate([{ transform: "scale(1)" }, { transform: "scale(0)" }], { duration: 180, easing: "ease-in", fill: "forwards" });
    glyphAnimation.current = animation;
    animation.finished.then(() => { if (glyphAnimation.current === animation) setGlyph(null); }, () => undefined);
  }, [targetGlyph, glyph, reduced]);

  React.useLayoutEffect(() => {
    const node = glyphRef.current;
    const first = !glyphMounted.current;
    glyphMounted.current = true;
    glyphAnimation.current?.cancel();
    glyphAnimation.current = null;
    if (glyph === null || reduced || !canAnimate(node)) return;
    glyphAnimation.current = node.animate([{ transform: "scale(0)" }, { transform: "scale(1)" }], { duration: GLYPH_MS, delay: first ? drawDelay + DRAW_MS * 0.6 : 0, easing: EASE, fill: "backwards" });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [glyph]);

  React.useEffect(() => () => { glyphAnimation.current?.cancel(); glyphMounted.current = false; }, []);

  const [announcement, setAnnouncement] = React.useState("");
  const announced = React.useRef(status);

  React.useEffect(() => {
    if (announced.current === status) return;
    announced.current = status;
    if (announce) setAnnouncement(`${displayName} is ${(statusLabel ?? AVATAR_STATUS_LABEL[status]).toLowerCase()}`);
  }, [status, announce, displayName, statusLabel]);

  const glyphSize = Math.min(18, Math.max(12, Math.round(size * 0.25)));
  const glyphOffset = geo.c + geo.r / Math.SQRT2 - glyphSize / 2;
  const glyphColor = glyph === "check" ? (tone?.online ?? STATUS_COLOR.online) : color;
  const raised = hovered || focused;
  const label = `${displayName}, ${phrase}`;
  const showImage = !!src && !failed;

  return (
    <div
      {...rest}
      ref={(node) => {
        rootRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) (ref as { current: HTMLDivElement | null }).current = node;
      }}
      role="img"
      aria-label={label}
      tabIndex={tabIndex}
      data-slot="avatar-status-ring"
      data-status={status}
      data-progress={uploading ? progressValue.toFixed(3) : undefined}
      data-level={status === "speaking" ? clamp01(level ?? 0.6).toFixed(3) : undefined}
      data-hovered={hovered ? "true" : "false"}
      onPointerEnter={(event) => { onPointerEnter?.(event); setHovered(true); }}
      onPointerLeave={(event) => { onPointerLeave?.(event); setHovered(false); }}
      onFocus={(event) => { onFocus?.(event); setFocused(true); }}
      onBlur={(event) => { onBlur?.(event); setFocused(false); setHovered(false); }}
      className={`group relative inline-flex shrink-0 items-center justify-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background [--asr-away:var(--color-chart-5)] dark:[--asr-away:var(--color-chart-3)] ${className}`}
      style={{ width: geo.box, height: geo.box, ...style, ...(raised ? { zIndex: 60 } : null) }}
    >
      <svg aria-hidden="true" viewBox={`0 0 ${geo.box} ${geo.box}`} width={geo.box} height={geo.box} className="pointer-events-none absolute inset-0 overflow-visible">
        {backdrop && <circle data-backdrop cx={geo.c} cy={geo.c} r={geo.box / 2} fill={surface} />}
        <circle ref={haloRef} data-ring-halo cx={geo.c} cy={geo.c} r={geo.r} fill="none" strokeWidth={ringWidth} style={{ stroke: color, opacity: 0, transition: reduced ? "none" : `stroke ${COLOR_MS}ms` }} />
        <circle
          data-ring-track
          cx={geo.c}
          cy={geo.c}
          r={geo.r}
          fill="none"
          stroke="var(--color-border)"
          strokeWidth={ringWidth}
          style={{ opacity: uploading ? 1 : 0, transition: reduced ? "none" : `opacity ${COLOR_MS}ms` }}
        />
        <circle
          ref={ringRef}
          data-ring
          cx={geo.c}
          cy={geo.c}
          r={geo.r}
          fill="none"
          strokeWidth={ringWidth}
          strokeLinecap="round"
          pathLength={1}
          transform={`rotate(-90 ${geo.c} ${geo.c})`}
          style={{ stroke: color, strokeDasharray: initial.current.dash, strokeDashoffset: `${initial.current.offset}px`, transition: reduced ? "none" : `stroke ${COLOR_MS}ms` }}
        />
      </svg>
      <span
        data-image
        className={`relative overflow-hidden rounded-full bg-muted transition-opacity duration-300 motion-reduce:transition-none ${status === "offline" ? "opacity-70" : "opacity-100"}`}
        style={{ width: size, height: size }}
      >
        {showImage ? (
          <img ref={imageRef} src={src} alt="" aria-hidden="true" draggable={false} onError={() => setFailedSrc(src ?? null)} className="size-full object-cover" />
        ) : (
          <span data-fallback className="flex size-full items-center justify-center text-muted-foreground">
            {fallback ?? <UserRound aria-hidden="true" strokeWidth={1.75} style={{ width: size * 0.55, height: size * 0.55 }} />}
          </span>
        )}
      </span>
      {glyph !== null && (
        <span
          ref={glyphRef}
          data-glyph={glyph}
          aria-hidden="true"
          className="absolute flex items-center justify-center rounded-full ring-1 ring-border [&>svg]:size-[62%]"
          style={{ width: glyphSize, height: glyphSize, left: glyphOffset, top: glyphOffset, background: surface, color: glyphColor, transition: reduced ? "none" : `color ${COLOR_MS}ms` }}
        >
          {GLYPH_ICON[glyph]}
        </span>
      )}
      {tooltip && (
        <span
          data-tooltip
          aria-hidden="true"
          data-shown={raised ? "true" : "false"}
          className={`pointer-events-none absolute bottom-full left-1/2 mb-1 -translate-x-1/2 whitespace-nowrap rounded-md bg-foreground px-2 py-1 text-[11px] font-medium leading-none text-background shadow-sm transition-[opacity,translate] duration-150 motion-reduce:transition-none ${raised ? "translate-y-0 opacity-100" : "translate-y-0.5 opacity-0"}`}
        >
          {displayName} · {phrase}
        </span>
      )}
      {announce && <span role="status" aria-live="polite" className="sr-only">{announcement}</span>}
    </div>
  );
}

export function AvatarStatusRingGroup({
  items,
  max = 5,
  size = 32,
  overlap,
  ringWidth = 2,
  showIcon,
  surface = "var(--color-background)",
  announce = false,
  overflowLabel = (hidden: number) => `+${hidden}`,
  drawDelay = 0,
  stagger = 80,
  "aria-label": ariaLabel,
  className = "",
  onKeyDown,
  ref,
  ...rest
}: AvatarStatusRingGroupProps) {
  const visible = items.slice(0, Math.max(0, max));
  const hidden = items.length - visible.length;
  const shift = overlap ?? Math.round(size * 0.35);
  const geo = geometry(size, ringWidth);
  const [focusIndex, setFocusIndex] = React.useState(0);
  const nodes = React.useRef([] as (HTMLDivElement | null)[]);
  const [announcement, setAnnouncement] = React.useState("");
  const seen = React.useRef({} as { [key: string]: AvatarStatus });

  React.useEffect(() => {
    const changes: string[] = [];
    for (const item of items) {
      const key = item.id ?? item.alt;
      const before = seen.current[key];
      if (before !== undefined && before !== item.status) changes.push(`${item.name ?? item.alt} is ${(item.statusLabel ?? AVATAR_STATUS_LABEL[item.status]).toLowerCase()}`);
      seen.current[key] = item.status;
    }
    if (announce && changes.length) setAnnouncement(changes.join(". "));
  }, [items, announce]);

  const moveFocus = (key: string) => {
    const count = visible.length;
    if (count === 0) return false;
    let next = -1;
    if (key === "ArrowRight") next = (focusIndex + 1) % count;
    else if (key === "ArrowLeft") next = (focusIndex - 1 + count) % count;
    else if (key === "Home") next = 0;
    else if (key === "End") next = count - 1;
    if (next < 0) return false;
    setFocusIndex(next);
    nodes.current[next]?.focus({ preventScroll: true });
    return true;
  };

  return (
    <div
      {...rest}
      ref={ref}
      role="group"
      aria-label={ariaLabel ?? `${items.length} people`}
      data-slot="avatar-status-ring-group"
      data-visible={visible.length}
      data-hidden={hidden}
      onKeyDown={(event) => { onKeyDown?.(event); if (!event.defaultPrevented && moveFocus(event.key)) event.preventDefault(); }}
      className={`inline-flex items-center ${className}`}
    >
      {visible.map((item, index) => {
        const { id, ...person } = item;
        return (
          <AvatarStatusRing
            key={id ?? person.alt}
            {...person}
            ref={(node) => { nodes.current[index] = node; }}
            size={size}
            ringWidth={ringWidth}
            showIcon={showIcon ?? size >= 40}
            backdrop
            surface={surface}
            drawDelay={drawDelay + index * stagger}
            tabIndex={index === focusIndex ? 0 : -1}
            onFocus={() => setFocusIndex(index)}
            data-index={index}
            style={{ marginLeft: index === 0 ? 0 : -shift, zIndex: index + 1 }}
          />
        );
      })}
      {hidden > 0 && (
        <span data-overflow className="relative inline-flex items-center justify-center" style={{ width: geo.box, height: geo.box, marginLeft: -shift, zIndex: visible.length + 1 }}>
          <span
            className="inline-flex items-center justify-center rounded-full bg-muted text-[11px] font-medium tabular-nums leading-none text-muted-foreground ring-1 ring-border"
            style={{ width: size, height: size, boxShadow: `0 0 0 2px ${surface}` }}
          >
            {overflowLabel(hidden)}
          </span>
        </span>
      )}
      {announce && <span role="status" aria-live="polite" className="sr-only">{announcement}</span>}
    </div>
  );
}

export default AvatarStatusRing;

