"use client";

import * as React from "react";
import { AVATAR_STATUS_LABEL, AvatarStatusRing, AvatarStatusRingGroup } from "@/components/ui/avatar-status-ring";
import type { AvatarStatus, AvatarStatusRingGroupItem } from "@/components/ui/avatar-status-ring";

type DemoProps = { autoplay?: boolean };

const HEADSHOTS = {
  "photo-1507003211169-0a1dd7228f2d": "data:image/webp;base64,",
  "photo-1573497019940-1c28c88b4f3e": "data:image/webp;base64,",
  "photo-1500648767791-00dcc994a43e": "data:image/webp;base64,",
  "photo-1494790108377-be9c29b29330": "data:image/webp;base64,",
  "photo-1560250097-0b93528c311a": "data:image/webp;base64,",
  "photo-1573496358961-3c82861ab8f4": "data:image/webp;base64,",
  "photo-1595211877493-41a4e5f236b3": "data:image/webp;base64,",
  "photo-1699899657680-421c2c2d5064": "data:image/webp;base64,",
  "photo-1705645930353-0e335311ef20": "data:image/webp;base64,",
} as const;

const photo = (id: keyof typeof HEADSHOTS) => HEADSHOTS[id];

const CALL = {
  jordan: { name: "Jordan Lee", photo: photo("photo-1507003211169-0a1dd7228f2d") },
  mina: { name: "Mina Park", photo: photo("photo-1573497019940-1c28c88b4f3e") },
  theo: { name: "Theo Alvarez", photo: photo("photo-1500648767791-00dcc994a43e") },
  sora: { name: "Sora Kim", photo: photo("photo-1494790108377-be9c29b29330") },
} as const;

type CallId = keyof typeof CALL;

const ORDER: CallId[] = ["jordan", "mina", "theo", "sora"];

type Presence = { status: AvatarStatus; level?: number; progress?: number };
type Presences = { [id in CallId]: Presence };

const INITIAL: Presences = {
  jordan: { status: "online" },
  mina: { status: "online" },
  theo: { status: "away" },
  sora: { status: "online" },
};

const LAB: Presences = {
  jordan: { status: "online" },
  mina: { status: "speaking", level: 0.2 },
  theo: { status: "away" },
  sora: { status: "uploading", progress: 0.25 },
};

const CHANNEL: AvatarStatusRingGroupItem[] = [
  { id: "lucas", name: "Lucas Moreau", alt: "Lucas Moreau", src: photo("photo-1560250097-0b93528c311a"), status: "online" },
  { id: "amara", name: "Amara Okafor", alt: "Amara Okafor", src: photo("photo-1573496358961-3c82861ab8f4"), status: "online" },
  { id: "noah", name: "Noah Fischer", alt: "Noah Fischer", src: photo("photo-1595211877493-41a4e5f236b3"), status: "away" },
  { id: "hanna", name: "Hanna Berg", alt: "Hanna Berg", src: photo("photo-1699899657680-421c2c2d5064"), status: "busy" },
  { id: "felix", name: "Felix Brandt", alt: "Felix Brandt", src: photo("photo-1705645930353-0e335311ef20"), status: "offline" },
  { id: "priya", name: "Priya Nair", alt: "Priya Nair", status: "online" },
  { id: "omar", name: "Omar Haddad", alt: "Omar Haddad", status: "offline" },
  { id: "elin", name: "Elin Sandberg", alt: "Elin Sandberg", status: "away" },
];

const WAVE = [0.35, 0.6, 0.85, 0.7, 0.4, 0.25, 0.3, 0.55, 0.9, 0.75, 0.5, 0.3, 0.2, 0.45, 0.8, 0.65, 0.4, 0.6, 0.85, 0.5, 0.3, 0.2, 0.4, 0.7, 0.9, 0.6, 0.35, 0.25, 0.5, 0.75, 0.55, 0.3];
const WAVE_MS = 60;
const UPLOAD_AT = 2200;
const UPLOAD_MS = 2400;
const UPLOAD_TICK_MS = 80;
const LOOP_MS = 9000;
const BROKEN_SRC = "data:image/webp;base64,AAAA";

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

const phraseOf = (presence: Presence) =>
  presence.status === "uploading" ? `${AVATAR_STATUS_LABEL.uploading} · ${Math.round(clamp01(presence.progress ?? 0) * 100)}%` : AVATAR_STATUS_LABEL[presence.status];

const isCallId = (value: unknown): value is CallId => typeof value === "string" && value in CALL;
const isStatus = (value: unknown): value is AvatarStatus => typeof value === "string" && value in AVATAR_STATUS_LABEL;

export default function Demo({ autoplay = true }: DemoProps) {
  const params = React.useMemo(() => new URLSearchParams(typeof window === "undefined" ? "" : window.location.search), []);
  const lab = params.get("lab") === "1";
  const broken = params.get("broken") === "1";
  const toned = params.get("tone") === "1";
  const thick = params.get("thick") === "1";
  const announceAll = params.get("announce") === "1";
  const [presences, setPresences] = React.useState(lab ? LAB : INITIAL);
  const [reduced, setReduced] = React.useState(true);
  const [paused, setPaused] = React.useState(false);
  const [run, setRun] = React.useState(0);
  const rootRef = React.useRef(null as HTMLElement | null);

  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  const patch = React.useCallback((id: CallId, next: Presence) => {
    setPresences((previous) => ({ ...previous, [id]: next }));
  }, []);

  React.useEffect(() => {
    if (!lab) return;
    const onLab = (event: Event) => {
      const detail: unknown = event instanceof CustomEvent ? event.detail : null;
      if (!detail || typeof detail !== "object") return;
      const { who, status, level, progress } = detail as { who?: unknown; status?: unknown; level?: unknown; progress?: unknown };
      if (!isCallId(who)) return;
      setPresences((previous) => {
        const current = previous[who];
        return {
          ...previous,
          [who]: {
            status: isStatus(status) ? status : current.status,
            level: typeof level === "number" ? level : current.level,
            progress: typeof progress === "number" ? progress : current.progress,
          },
        };
      });
    };
    window.addEventListener("asr-lab", onLab);
    return () => window.removeEventListener("asr-lab", onLab);
  }, [lab]);

  React.useEffect(() => {
    if (!autoplay || lab || paused) return;
    const root = rootRef.current;
    const started = performance.now();
    let steps = 0;
    const timers: number[] = [];
    const intervals: number[] = [];
    if (root) {
      root.dataset.tourStarted = started.toFixed(1);
      root.dataset.tourStep = "0";
    }
    const at = (ms: number, action: () => void) => {
      timers.push(window.setTimeout(() => {
        action();
        steps += 1;
        if (root) {
          root.dataset.tourStep = String(steps);
          root.dataset.tourLastAt = (performance.now() - started).toFixed(1);
        }
      }, ms));
    };
    let wave = 0;
    at(800, () => {
      patch("mina", { status: "speaking", level: reduced ? 0.6 : WAVE[0] });
      if (reduced) return;
      intervals.push(window.setInterval(() => {
        wave += 1;
        patch("mina", { status: "speaking", level: WAVE[wave % WAVE.length] ?? 0.5 });
      }, WAVE_MS));
    });
    at(UPLOAD_AT, () => {
      patch("sora", { status: "uploading", progress: 0 });
      const ticker = window.setInterval(() => {
        const value = clamp01((performance.now() - started - UPLOAD_AT) / UPLOAD_MS);
        patch("sora", { status: "uploading", progress: value });
        if (value >= 1) window.clearInterval(ticker);
      }, UPLOAD_TICK_MS);
      intervals.push(ticker);
    });
    at(3400, () => patch("jordan", { status: "away" }));
    at(UPLOAD_AT + UPLOAD_MS, () => patch("sora", { status: "uploading", progress: 1 }));
    at(UPLOAD_AT + UPLOAD_MS + 200, () => patch("sora", { status: "online" }));
    at(5400, () => patch("theo", { status: "busy" }));
    at(6200, () => {
      intervals.forEach((interval) => window.clearInterval(interval));
      patch("mina", { status: "online" });
    });
    at(LOOP_MS, () => {
      setPresences(INITIAL);
      setRun((previous) => previous + 1);
    });
    return () => {
      timers.forEach((timer) => window.clearTimeout(timer));
      intervals.forEach((interval) => window.clearInterval(interval));
    };
  }, [autoplay, lab, paused, reduced, run, patch]);

  const takeOver = () => { if (autoplay && !lab) setPaused(true); };

  return (
    <main
      ref={rootRef}
      data-demo="avatar-status-ring"
      data-paused={paused ? "true" : "false"}
      className="flex w-full items-center justify-center bg-background p-4 text-foreground"
      style={{ height: "min(100svh, 640px)" }}
      onPointerDownCapture={takeOver}
      onKeyDownCapture={takeOver}
    >
      <section
        aria-label="Design sync"
        className="w-full max-w-[560px] rounded-2xl bg-card p-5 text-card-foreground ring-1 ring-border shadow-[0_16px_40px_-24px_color-mix(in_oklch,var(--color-foreground)_40%,transparent)]"
      >
        <header className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <p className="truncate text-sm font-medium leading-5">Design sync</p>
            <p className="truncate text-xs leading-4 text-muted-foreground">Weekly · Room 2</p>
          </div>
          <p className="shrink-0 pt-0.5 text-xs tabular-nums leading-4 text-muted-foreground">14:00 – 14:30</p>
        </header>
        <ul className="mt-5 grid grid-cols-4 gap-2">
          {ORDER.map((id, index) => {
            const person = CALL[id];
            const presence = presences[id];
            return (
              <li key={id} className="flex min-w-0 flex-col items-center text-center">
                <AvatarStatusRing
                  src={id === "sora" && broken ? BROKEN_SRC : person.photo}
                  alt={person.name}
                  name={person.name}
                  size={64}
                  status={presence.status}
                  level={presence.level}
                  progress={presence.progress}
                  drawDelay={index * 80}
                  surface="var(--color-card)"
                  tone={id === "jordan" && toned ? { online: "var(--color-chart-3)" } : undefined}
                  ringWidth={id === "theo" && thick ? 4 : undefined}
                  showIcon={id === "theo" && thick ? false : undefined}
                  announce={announceAll}
                  data-person={id}
                />
                <p className="mt-2 max-w-full truncate text-sm font-medium leading-5">{person.name}</p>
                <p data-status-text className="max-w-full truncate text-xs tabular-nums leading-4 text-muted-foreground">{phraseOf(presence)}</p>
              </li>
            );
          })}
        </ul>
        <div className="mt-5 flex items-center justify-between gap-4 border-t border-border pt-4">
          <p className="truncate text-xs leading-4 text-muted-foreground">Also in #design</p>
          <AvatarStatusRingGroup
            items={CHANNEL}
            max={5}
            size={32}
            ringWidth={2}
            surface="var(--color-card)"
            drawDelay={320}
            stagger={80}
            announce={announceAll}
            aria-label="Also in #design"
            className="shrink-0"
          />
        </div>
      </section>
    </main>
  );
}
